  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Absolute Monarchy, Constitutional Government and the Enlightenment$j$, $j${"readings": [{"title": "Proverbs 29 (King James Version)", "url": "/portal/bible/Proverbs/29"}], "body": "Two ideas of government clashed in the 1600s and 1700s. In an absolute monarchy, the king holds all power, claiming his right comes from God. Louis XIV of France, the Sun King, ruled this way and built the palace of Versailles. In a constitutional monarchy, law limits the ruler. In England the Glorious Revolution of 1688 removed James II, and the English Bill of Rights of 1689 gave Parliament power over taxes and laws.\n\nThe Enlightenment, or Age of Reason, was a movement that used reason to study society and government. Key thinkers:\nJohn Locke taught that people have natural rights to life, liberty and property, and that government rests on consent.\nMontesquieu urged the separation of powers among branches of government.\nVoltaire defended freedom of speech and religion.\nJean Jacques Rousseau wrote about the social contract and the general will.\nAdam Smith described free markets in The Wealth of Nations in 1776.\n\nThese ideas shaped the American Declaration of Independence in 1776 and later constitutions. Christians noted that the Bible already taught human dignity and limits on rulers, while some Enlightenment thinkers criticized the Church. Students must weigh each idea carefully, holding what is good. Proverbs 29:2 says, When the righteous are in authority, the people rejoice: but when the wicked beareth rule, the people mourn.\n\nYour task: (1) Compare absolute and constitutional monarchy. (2) Match thinker to idea: Locke, Montesquieu, Voltaire. (3) Name one way Enlightenment ideas influenced the American founding.\n\nFlorida standards: SS.912.W.5.1, SS.912.W.5.2, SS.912.W.5.3, SS.912.W.5.4, SS.912.W.5.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.5.1, SS.912.W.5.2, SS.912.W.5.3, SS.912.W.5.4, SS.912.W.5.5", "script": "Welcome to Unit 6. Listen, we now move into the age of revolutions. Two ideas of government clashed in the sixteen hundreds and seventeen hundreds. In an absolute monarchy the king holds all power, claiming his right comes from God. Louis the Fourteenth of France, the Sun King, ruled this way and built the palace of Versailles. In a constitutional monarchy, law limits the ruler. In England the Glorious Revolution of sixteen eighty eight removed James the Second, and the English Bill of Rights of sixteen eighty nine gave Parliament power over taxes and laws.\n\nNow watch this. The Enlightenment, or Age of Reason, used reason to study society and government. John Locke taught natural rights to life, liberty and property and that government rests on consent. Montesquieu urged separation of powers. Voltaire defended freedom of speech and religion. Rousseau wrote about the social contract. And Adam Smith described free markets in The Wealth of Nations in seventeen seventy six.\n\nLook at this. These ideas shaped the American Declaration of Independence and later constitutions. Christians noted that the Bible already taught human dignity and limits on rulers, while some Enlightenment thinkers criticized the Church. So we weigh each idea carefully and hold fast to what is good. Proverbs twenty nine and two says, When the righteous are in authority, the people rejoice: but when the wicked beareth rule, the people mourn.\n\nYour task today. Compare absolute and constitutional monarchy. Match thinkers to ideas. And name one way Enlightenment ideas influenced the American founding. Take the four question check.\n\nRighteous rule blesses a people. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Absolute Monarchy, Constitutional Government and the Enlightenment$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 The French Revolution, Napoleon and Independence in Latin America$j$, $j${"readings": [{"title": "Galatians 5 (King James Version)", "url": "/portal/bible/Galatians/5"}], "body": "France in 1789 had a king, Louis XVI, huge debt and a society of three estates: the clergy, the nobles and everyone else. The Third Estate paid most of the taxes yet had little power. When the Estates General met in 1789, the Third Estate formed a National Assembly. On July 14 a crowd stormed the Bastille prison. The Assembly issued the Declaration of the Rights of Man and of the Citizen, announcing liberty and equality before the law.\n\nThe Revolution then turned violent. The king was executed in 1793, and during the Reign of Terror Maximilien Robespierre's government executed thousands, including many ordinary people. Priests were persecuted and churches closed. Then Napoleon Bonaparte, a general, took power in 1799 and crowned himself emperor in 1804. His Napoleonic Code organized law. His armies conquered much of Europe, but his invasion of Russia in 1812 failed, and he was defeated at Waterloo in 1815. The Congress of Vienna tried to restore order.\n\nRevolution spread across the Atlantic. In Haiti, enslaved people led by Toussaint Louverture rose, and Haiti became independent in 1804. In South America, Simon Bolivar and Jose de San Martin led wars of independence against Spain. Mexico won independence in 1821 and Brazil in 1822. Galatians 5:1 says, Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage.\n\nYour task: (1) Give two causes of the French Revolution. (2) Tell what the Reign of Terror shows about revolutions that lose their moral base. (3) Name two leaders of Latin American independence.\n\nFlorida standards: SS.912.W.5.6, SS.912.W.5.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.5.6, SS.912.W.5.7", "script": "Welcome back. Listen, France in seventeen eighty nine had a king, Louis the Sixteenth, huge debt, and a society of three estates, the clergy, the nobles and everyone else. The Third Estate paid most of the taxes yet had little power. When the Estates General met, the Third Estate formed a National Assembly. On July fourteenth a crowd stormed the Bastille prison. The Assembly issued the Declaration of the Rights of Man and of the Citizen, announcing liberty and equality before the law.\n\nNow watch this. The Revolution turned violent. The king was executed in seventeen ninety three, and in the Reign of Terror, Robespierre's government executed thousands, including many ordinary people. Priests were persecuted and churches closed. Then a general, Napoleon Bonaparte, took power in seventeen ninety nine and crowned himself emperor in eighteen oh four. His Napoleonic Code organized law. His armies conquered much of Europe, but his invasion of Russia in eighteen twelve failed, and he fell at Waterloo in eighteen fifteen. The Congress of Vienna tried to restore order.\n\nLook at this. Revolution spread across the Atlantic. In Haiti, enslaved people led by Toussaint Louverture rose, and Haiti won independence in eighteen oh four. In South America, Simon Bolivar and Jose de San Martin led wars of independence against Spain. Mexico won independence in eighteen twenty one and Brazil in eighteen twenty two. Galatians five and one says, Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage.\n\nYour task today. Give two causes of the French Revolution. Tell what the Terror shows about revolutions that lose their moral base. And name two leaders of Latin American independence. Take the four question check.\n\nTrue liberty rests on truth. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 The French Revolution, Napoleon and Independence in Latin America$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Industrial Revolution, New Ideas, Nations and Empires$j$, $j${"readings": [{"title": "James 5 (King James Version)", "url": "/portal/bible/James/5"}], "body": "The Industrial Revolution began in Britain in the 1700s and changed how people lived and worked. Why Britain? It had coal and iron, capital, a growing population, a strong navy, colonies for raw materials and markets, and improved farming. Key innovations were the spinning jenny, James Watt's improved steam engine, the factory and the railroad.\n\nEffects were large. Cities grew fast, and many workers, including children, labored long hours in poor conditions. Wages and goods eventually rose, and a middle class grew. Reformers acted. Parliament passed Factory Acts, workers formed unions, and William Wilberforce and others won the end of slavery in the British Empire in 1833. James 5:4 says, Behold, the hire of the labourers who have reaped down your fields, which is of you kept back by fraud, crieth: and the cries of them which have reaped are entered into the ears of the Lord of sabaoth.\n\nThree economic ideas competed. Capitalism rests on private property and free markets. Socialism urges that the community own major industries. Communism, taught by Karl Marx in the Communist Manifesto of 1848, called for class struggle and rejected God, and later communist governments denied religious freedom.\n\nNationalism pushed Italy to unify by 1861 under Cavour and Garibaldi, and Germany by 1871 under Bismarck and Prussia.\n\nImperialism followed. Nations competed for colonies for raw materials, markets and power, sometimes saying they were bringing civilization or the gospel. The Berlin Conference of 1884 divided Africa. Britain ruled India. In China the Opium Wars of 1839 to 1842 and 1856 to 1860 opened the country to Western trade, and the Taiping Rebellion caused enormous loss of life. Japan modernized under the Meiji emperor from 1868.\n\nYour task: (1) Give three reasons the Industrial Revolution began in Britain. (2) Compare capitalism, socialism and communism. (3) Explain two causes and two effects of imperialism.\n\nFlorida standards: SS.912.W.6.1, SS.912.W.6.2, SS.912.W.6.3, SS.912.W.6.4, SS.912.W.6.5, SS.912.W.6.6, SS.912.W.6.7.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.6.1, SS.912.W.6.2, SS.912.W.6.3, SS.912.W.6.4, SS.912.W.6.5, SS.912.W.6.6, SS.912.W.6.7", "script": "Welcome back. Listen, the Industrial Revolution began in Britain in the seventeen hundreds and changed how people lived and worked. Why Britain? It had coal and iron, capital, a growing population, a strong navy, colonies for raw materials and markets, and better farming. Key innovations were the spinning jenny, James Watt's improved steam engine, the factory and the railroad.\n\nNow watch this. The effects were large. Cities grew fast, and many workers, including children, labored long hours in poor conditions. Wages and goods eventually rose, and a middle class grew. Reformers acted. Parliament passed Factory Acts, workers formed unions, and William Wilberforce and others won the end of slavery in the British Empire in eighteen thirty three. James five and four says, Behold, the hire of the labourers who have reaped down your fields, which is of you kept back by fraud, crieth: and the cries of them which have reaped are entered into the ears of the Lord of sabaoth.\n\nLook at this. Three economic ideas competed. Capitalism rests on private property and free markets. Socialism urges that the community own major industries. Communism, taught by Karl Marx in the Communist Manifesto of eighteen forty eight, called for class struggle and rejected God, and later communist governments denied religious freedom.\n\nNationalism pushed Italy to unify by eighteen sixty one under Cavour and Garibaldi, and Germany by eighteen seventy one under Bismarck and Prussia. Then came imperialism. Nations competed for colonies for raw materials, markets and power. The Berlin Conference of eighteen eighty four divided Africa. Britain ruled India. In China the Opium Wars opened the country to Western trade, and Japan modernized under the Meiji emperor from eighteen sixty eight.\n\nYour task today. Give three reasons the Industrial Revolution began in Britain. Compare capitalism, socialism and communism. And explain two causes and two effects of imperialism. Take the four question check.\n\nJustice for the worker matters to God. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Industrial Revolution, New Ideas, Nations and Empires$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 The Twentieth Century: World Wars, the Holocaust and the Cold War$j$, $j${"readings": [{"title": "Psalm 33 (King James Version)", "url": "/portal/bible/Psalms/33"}], "body": "This lesson gives an overview of the twentieth century. It is a survey that prepares you for deeper study in a later course.\n\nWorld War I, 1914 to 1918: The long term causes were militarism, alliances, imperialism and nationalism, often remembered as MAIN. The trigger was the assassination of Archduke Franz Ferdinand in Sarajevo on June 28, 1914. Trench warfare, machine guns and poison gas killed millions. The Treaty of Versailles in 1919 punished Germany, and many historians say its harshness helped feed later anger. In 1917 Vladimir Lenin led a communist revolution in Russia.\n\nBetween the wars: The Great Depression began in 1929. Dictators rose: Stalin in the Soviet Union, Mussolini in Italy and Adolf Hitler in Germany.\n\nWorld War II, 1939 to 1945: Germany invaded Poland in 1939. Japan attacked Pearl Harbor in 1941. Allied forces landed in Normandy on D Day in 1944. The war ended in 1945 after the atomic bombs on Japan. About 70 million people died.\n\nThe Holocaust: The Nazi regime murdered about six million Jewish people, along with millions of others, in a plan of genocide. Many Christians such as Dietrich Bonhoeffer and Corrie ten Boom resisted and helped to rescue Jewish neighbors. We remember so that such evil never happens again.\n\nThe Cold War, 1945 to 1991: The United States and the Soviet Union competed without direct war between them, through alliances such as NATO and the Warsaw Pact, an arms race, and conflicts such as Korea and Vietnam. The Berlin Wall was built in 1961 and fell in 1989. The Soviet Union collapsed in 1991. During these years many colonies, such as India in 1947, became independent nations, China became communist in 1949, and Israel was founded in 1948.\n\nPsalm 33:12 says, Blessed is the nation whose God is the LORD; and the people whom he hath chosen for his own inheritance.\n\nYour task: (1) Name the MAIN causes of World War I. (2) Explain what the Holocaust was and why we remember it. (3) Name two events of the Cold War and tell how it ended.\n\nFlorida standards: SS.912.W.7.1, SS.912.W.8.1, SS.912.W.9.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SS.912.W.7.1, SS.912.W.8.1, SS.912.W.9.1", "script": "Welcome back. Listen, this lesson is an overview of the twentieth century, and it prepares you for deeper study later.\n\nNow watch this. World War One, nineteen fourteen to nineteen eighteen. The long term causes were militarism, alliances, imperialism and nationalism, remembered as MAIN. The trigger was the assassination of Archduke Franz Ferdinand in Sarajevo on June twenty eighth, nineteen fourteen. Trench warfare, machine guns and poison gas killed millions. The Treaty of Versailles in nineteen nineteen punished Germany, and many historians say its harshness helped feed later anger. In nineteen seventeen Lenin led a communist revolution in Russia.\n\nBetween the wars the Great Depression began in nineteen twenty nine, and dictators rose, Stalin in the Soviet Union, Mussolini in Italy and Adolf Hitler in Germany. World War Two began when Germany invaded Poland in nineteen thirty nine. Japan attacked Pearl Harbor in nineteen forty one. Allied forces landed in Normandy in nineteen forty four. The war ended in nineteen forty five, and about seventy million people died.\n\nHear this with respect. The Holocaust. The Nazi regime murdered about six million Jewish people, along with millions of others, in a plan of genocide. Many Christians, such as Dietrich Bonhoeffer and Corrie ten Boom, resisted and helped rescue Jewish neighbors. We remember so that such evil never happens again.\n\nLook at this. In the Cold War, nineteen forty five to nineteen ninety one, the United States and the Soviet Union competed without direct war between them, through alliances such as NATO and the Warsaw Pact, an arms race, and conflicts such as Korea and Vietnam. The Berlin Wall was built in nineteen sixty one and fell in nineteen eighty nine. The Soviet Union collapsed in nineteen ninety one. Many colonies, like India in nineteen forty seven, became independent, China became communist in nineteen forty nine, and Israel was founded in nineteen forty eight.\n\nPsalm thirty three and twelve says, Blessed is the nation whose God is the LORD; and the people whom he hath chosen for his own inheritance.\n\nYour task today. Name the MAIN causes of World War One. Explain what the Holocaust was and why we remember it. And name two Cold War events and tell how it ended. Take the four question check.\n\nTruth and righteousness must guard every generation. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 The Twentieth Century: World Wars, the Holocaust and the Cold War$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Revolutions and the Modern World$j$, $j${"prompt": "Write an essay answering this question: How did new ideas change governments and economies from 1688 to the present? Use complete sentences and label each part. Psalm 33:12 says, Blessed is the nation whose God is the LORD; and the people whom he hath chosen for his own inheritance.\n\nPart 1: Explain two Enlightenment ideas and how each influenced a later revolution or constitution.\nPart 2: Compare the French Revolution with the independence movements in Haiti or Latin America, giving one similarity and one difference.\nPart 3: Explain how the Industrial Revolution changed work, cities and families, and tell how reformers responded.\nPart 4: Compare capitalism, socialism and communism, and explain one strength and one weakness of each from a Biblical viewpoint.\nPart 5: Explain two causes and two effects of imperialism, naming one region affected.\nPart 6: Choose one twentieth century event (World War I, World War II, the Holocaust or the Cold War) and explain its causes, its effects and what we should learn from it.", "rubric": "70 points. Enlightenment ideas: 10 points. Revolutions compared: 10 points. Industrial changes and reform: 10 points. Economic systems compared: 12 points. Imperialism: 10 points. Twentieth century event: 14 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Revolutions and the Modern World$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Freedom, Justice and the Role of Faith$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains why Enlightenment ideas about rights and limited government mattered, (2) describes one way a revolution lost its moral direction and what that teaches us, (3) tells how Christians such as Wilberforce, Bonhoeffer or Corrie ten Boom acted on their faith in hard times, and (4) connects your answer to Galatians 5:1, which says, Stand fast therefore in the liberty wherewith Christ hath made us free, and be not entangled again with the yoke of bondage. Then write a respectful reply of at least 40 words to another student, or answer this question: Why must a free people remember the Holocaust? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Freedom, Justice and the Role of Faith$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Absolute Monarchy, Constitutional Government and the Enlightenment$j$, $j${"questions": [{"q": "An absolute monarch:", "options": ["Is chosen by lot", "Shares power with Parliament", "Has no authority", "Holds all power in the state"]}, {"q": "The English Bill of Rights (1689) gave more power to:", "options": ["Parliament", "The Pope", "The sultan", "The Czar"]}, {"q": "John Locke taught that people have natural rights to:", "options": ["Life, liberty and property", "Ruling without law", "Silence", "Wealth from conquest"]}, {"q": "Montesquieu proposed:", "options": ["Serfdom", "Absolute monarchy", "Separation of powers", "Mercantilism"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Absolute Monarchy, Constitutional Government and the Enlightenment$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,0,2}'::int[], array[$j$Louis XIV is the standard example.$j$,$j$It limited the monarch and protected Parliament.$j$,$j$Locke's ideas influenced the Declaration of Independence.$j$,$j$Dividing power among branches protects liberty.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Absolute Monarchy, Constitutional Government and the Enlightenment$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: The French Revolution, Napoleon and Independence in Latin America$j$, $j${"questions": [{"q": "The Bastille was stormed on:", "options": ["October 31, 1517", "July 14, 1789", "December 7, 1941", "June 28, 1914"]}, {"q": "Napoleon crowned himself emperor in:", "options": ["1815", "1848", "1804", "1789"]}, {"q": "Napoleon was finally defeated at:", "options": ["Hastings", "Tours", "Waterloo", "Yorktown"]}, {"q": "Simon Bolivar helped win independence for:", "options": ["Ethiopia", "Parts of South America", "Japan", "Poland"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: The French Revolution, Napoleon and Independence in Latin America$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,1}'::int[], array[$j$The storming became a symbol of the Revolution.$j$,$j$He became Emperor of the French in 1804.$j$,$j$He lost at Waterloo in 1815.$j$,$j$He led forces against Spain in northern South America.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: The French Revolution, Napoleon and Independence in Latin America$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Industrial Revolution, New Ideas, Nations and Empires$j$, $j${"questions": [{"q": "The Industrial Revolution began in:", "options": ["Brazil", "Japan", "Britain", "Egypt"]}, {"q": "James Watt improved the:", "options": ["Printing press", "Steam engine", "Compass", "Telescope"]}, {"q": "Germany was unified in 1871 under:", "options": ["Prussia and Bismarck", "Louis XIV", "The Pope", "Napoleon"]}, {"q": "The Berlin Conference of 1884 was about:", "options": ["Dividing Africa among European powers", "Ending slavery in Brazil", "Opening Japan", "Unifying Italy"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Industrial Revolution, New Ideas, Nations and Empires$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,0,0}'::int[], array[$j$Coal, iron, capital and colonies helped Britain lead.$j$,$j$The steam engine powered factories and trains.$j$,$j$Bismarck used diplomacy and war to unify Germany.$j$,$j$African leaders were not part of the decisions.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Industrial Revolution, New Ideas, Nations and Empires$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: The Twentieth Century: World Wars, the Holocaust and the Cold War$j$, $j${"questions": [{"q": "The trigger of World War I was the assassination of:", "options": ["Napoleon", "Kaiser Wilhelm", "Archduke Franz Ferdinand", "Czar Nicholas"]}, {"q": "World War II in Europe began when Germany invaded:", "options": ["Poland", "Britain", "France", "Spain"]}, {"q": "The Holocaust was the:", "options": ["Nazi genocide of about six million Jews and others", "Plague of 1347", "French Reign of Terror", "Crusade of 1095"]}, {"q": "The Cold War ended with the:", "options": ["Opening of Japan", "Treaty of Versailles", "Collapse of the Soviet Union in 1991", "Fall of Constantinople"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: The Twentieth Century: World Wars, the Holocaust and the Cold War$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,0,2}'::int[], array[$j$He was killed in Sarajevo on June 28, 1914.$j$,$j$The invasion of Poland came in 1939.$j$,$j$It is remembered so that such evil is not repeated.$j$,$j$The Berlin Wall fell in 1989 and the USSR dissolved in 1991.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: The Twentieth Century: World Wars, the Holocaust and the Cold War$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Enlightenment, Revolutions, Industry, Empire and the Modern World$j$, $j${"questions": [{"q": "The Enlightenment is also called the:", "options": ["Age of Reason", "Dark Ages", "Age of Chivalry", "Age of Feudalism"]}, {"q": "The Declaration of the Rights of Man and of the Citizen came from the:", "options": ["American Civil War", "Meiji Restoration", "Crusades", "French Revolution"]}, {"q": "Toussaint Louverture led a revolution in:", "options": ["Haiti", "Spain", "Peru", "India"]}, {"q": "Which was a result of the Industrial Revolution?", "options": ["The return of feudalism", "The fall of Rome", "Rapid growth of cities", "The end of all factories"]}, {"q": "William Wilberforce is known for working to end:", "options": ["The Reformation", "The slave trade and slavery in the British Empire", "The printing press", "The Hundred Years War"]}, {"q": "Imperialism means:", "options": ["A church council", "Free elections", "A trade union", "A stronger nation extending control over other lands"]}, {"q": "The Cold War was a struggle between:", "options": ["England and France", "Rome and Persia", "The United States and the Soviet Union", "Japan and China only"]}, {"q": "The Treaty of Versailles (1919) ended:", "options": ["World War II", "The Crusades", "World War I", "The Cold War"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Enlightenment, Revolutions, Industry, Empire and the Modern World$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,0,2,1,3,2,2}'::int[], array[$j$Thinkers used reason to study government and society.$j$,$j$It was issued in 1789.$j$,$j$Haiti became independent in 1804.$j$,$j$People moved to cities for factory work.$j$,$j$Slavery ended in the British Empire in 1833.$j$,$j$Nations built empires for resources, markets and power.$j$,$j$They never fought directly but competed worldwide.$j$,$j$It placed heavy penalties on Germany.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Enlightenment, Revolutions, Industry, Empire and the Modern World$j$ on conflict (item_id) do nothing;
